import sys, os, re
sys.stdout.reconfigure(encoding='utf-8')
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(root)
sys.path.insert(0, os.path.join(root, 'test'))
import gen_iso_v9 as G

P = 'index.html'
s = open(P, encoding='utf-8').read()

def rep(old, new, n=1):
    global s
    c = s.count(old)
    assert c == n, ('count', c, n, old[:70])
    s = s.replace(old, new)

# ---------- 그림(인라인 SVG) 교체: viewBox 로 찾음 ----------
def swap_svg(viewbox, new_svg):
    global s
    pat = re.compile(r'<svg viewBox="%s"[^>]*>.*?</svg>' % re.escape(viewbox), re.S)
    m = pat.findall(s); assert len(m) == 1, (viewbox, len(m))
    s = pat.sub(lambda _: new_svg, s, count=1)
swap_svg('0 0 1260 750', G.cutaway())
swap_svg('0 0 1622 400', G.sequence())
swap_svg('0 0 1250 980', G.exploded())
swap_svg('0 0 1200 520', G.heating())

